// End-to-end: the Library (#12) through the running compose stack, from the users' side. The ingest script itself
// needs standardebooks.org and hours of narration, so it is covered by api/test/library.test.ts; here a short Book
// generated by the real worker is turned into a Library Book the way ingest leaves one (no owner, a book list key, a
// difficulty), and two users meet it in the 书库. Needs `npm run e2e:up`.
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import type { Book, LibraryBook, User } from "../api/src/contract.js";
import { endOpenJobs, fetchBytes, newUser, SHORT_WALK, sql, upload, waitForBook } from "./support.js";

let bookId: string;
const KEY = `e2e/short-walk-${Date.now()}`;

beforeAll(async () => {
  endOpenJobs();
  const created = await upload("short-walk.epub", SHORT_WALK);
  expect(created.status).toBe(201);
  bookId = created.body.id;
  await waitForBook(bookId, (b) => b.status === "ready", 180_000);
  sql(
    `update books set source = 'library', owner_id = null, library_key = '${KEY}', difficulty = 'beginner', ` +
      `blurb = '两章的短篇，适合试听。' where id = '${bookId}'`,
  );
  sql(`delete from shelf_entries where book_id = '${bookId}'`);
}, 240_000);

// Other runs' 书库 should not list this Book.
afterAll(() => {
  if (bookId) sql(`delete from books where id = '${bookId}'`);
});

const listen = (user: Awaited<ReturnType<typeof newUser>>, positionMs: number) =>
  user.api(`/books/${bookId}/listening`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ positionMs }),
  });

describe("the 书库 (F6, PRD 4.2.2)", () => {
  it("adds a Library Book to the Shelf and serves its first segment within 3 seconds (AC-LIB-01, AC-LIB-02)", async () => {
    const user = await newUser("library");
    const listed = (await user.api<LibraryBook[]>("/library")).body.find((b) => b.id === bookId);
    expect(listed).toMatchObject({ difficulty: "beginner", blurb: "两章的短篇，适合试听。", onShelf: false });

    const started = Date.now();
    expect((await user.api(`/books/${bookId}/shelf`, { method: "PUT" })).status).toBe(204);
    const playlist = await fetchBytes(`/api/books/${bookId}/audio.m3u8`, user.cookie);
    expect(playlist.status).toBe(200);
    const segment = new TextDecoder().decode(playlist.bytes).split("\n").find((l) => l.endsWith(".ts"))!;
    expect((await fetchBytes(`/api/books/${bookId}/${segment}`, user.cookie)).status).toBe(200);
    expect(Date.now() - started).toBeLessThan(3000);

    expect((await user.api<LibraryBook[]>("/library")).body.find((b) => b.id === bookId)).toMatchObject({ onShelf: true });
    expect((await user.api<Book[]>("/books")).body).toMatchObject([{ id: bookId, source: "library", status: "ready" }]);
  });

  it("shares the audio while each user keeps their own progress, and 移出书架 drops only theirs (PRD 4.2.3)", async () => {
    const [a, b] = [await newUser("library-a"), await newUser("library-b")];
    for (const u of [a, b]) await u.api(`/books/${bookId}/shelf`, { method: "PUT" });
    expect((await listen(a, 5000)).status).toBe(204);

    expect((await a.api<Book[]>("/books")).body[0]!.listening).not.toBeNull();
    expect((await b.api<Book[]>("/books")).body[0]!.listening).toBeNull();

    expect((await a.api(`/books/${bookId}/shelf`, { method: "DELETE" })).status).toBe(204);
    expect((await a.api<Book[]>("/books")).body).toEqual([]);
    expect((await b.api<Book[]>("/books")).body).toMatchObject([{ id: bookId }]);
    expect((await fetchBytes(`/api/books/${bookId}/audio.m3u8`, b.cookie)).status).toBe(200);
    // No user can delete the shared Book.
    expect((await b.api(`/books/${bookId}`, { method: "DELETE" })).status).toBe(404);
  });
});

describe("the first-play guide (F2, AC-GUIDE-02)", () => {
  it("is shown to a new user until they close it once", async () => {
    const user = await newUser("guide");
    expect((await user.api<User>("/me")).body.playGuideSeen).toBe(false);
    expect((await user.api("/me/play-guide", { method: "PUT" })).status).toBe(204);
    expect((await user.api<User>("/me")).body.playGuideSeen).toBe(true);
  });
});
